Cheapest defensible implementation, two parts. (a) Text: add a trigger-enforced denylist so it cannot be bypassed by a direct PostgREST call —
```sql
create table public.banned_terms (term text primary key);
create or replace function public.reject_banned_terms() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from public.banned_terms b
             where lower(coalesce(new.content, new.title || ' ' || coalesce(new.description,''))) like '%' || b.term || '%')
  then raise exception 'content_rejected' using errcode = 'P0004'; end if;
  return new;
end; $$;
create trigger msg_filter before insert on public.move_messages for each row execute function public.reject_banned_terms();
create trigger move_filter before insert or update on public.moves for each row execute function public.reject_banned_terms();
```
